final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Hourly AWS Organizations account-closure workflow. An Amazon EventBridge rule runs every
  hour and starts an EXPRESS AWS Step Functions state machine that paginates through the
  accounts in the organization, closes every ACTIVE account tagged
  organizations:account-closure=REQUESTED, overwrites that tag with ACKNOWLEDGED so the
  account is not processed again, and stores 365 days of execution data in a CloudWatch
  Logs log group. All resources are created by this template; no external infrastructure
  is referenced.

Resources:

  AccountClosureLogGroup:
    Type: AWS::Logs::LogGroup
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      LogGroupName: /aws/vendedlogs/states/account-closure-workflow
      RetentionInDays: 365

  AccountClosureWorkflowRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Execution role assumed by the account-closure EXPRESS state machine.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Sid: AllowStepFunctionsServiceToAssumeRole
            Effect: Allow
            Principal:
              Service: states.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: OrganizationsAccountClosure
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: AllowListAccountsAndDescribeOrganization
                Effect: Allow
                Action:
                  - organizations:ListAccounts
                  - organizations:DescribeOrganization
                Resource: '*'
              - Sid: AllowAccountClosureAndAccountTagging
                Effect: Allow
                Action:
                  - organizations:ListTagsForResource
                  - organizations:DescribeAccount
                  - organizations:CloseAccount
                  - organizations:TagResource
                Resource: !Sub 'arn:${AWS::Partition}:organizations::${AWS::AccountId}:account/*'
        - PolicyName: WriteStepFunctionsExecutionLogs
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: AllowCloudWatchLogDelivery
                Effect: Allow
                Action:
                  - logs:CreateLogDelivery
                  - logs:GetLogDelivery
                  - logs:UpdateLogDelivery
                  - logs:DeleteLogDelivery
                  - logs:ListLogDeliveries
                  - logs:PutResourcePolicy
                  - logs:DescribeResourcePolicies
                  - logs:DescribeLogGroups
                Resource: '*'
              - Sid: AllowExecutionLogWrites
                Effect: Allow
                Action:
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource: !Sub '${AccountClosureLogGroup.Arn}:*'

  AccountClosureStateMachine:
    Type: AWS::StepFunctions::StateMachine
    Properties:
      StateMachineName: account-closure-workflow
      StateMachineType: EXPRESS
      RoleArn: !GetAtt AccountClosureWorkflowRole.Arn
      LoggingConfiguration:
        Destinations:
          - CloudWatchLogsLogGroup:
              LogGroupArn: !Sub '${AccountClosureLogGroup.Arn}:*'
        IncludeExecutionData: true
        Level: ALL
      DefinitionString: !Sub |
        {
          "Comment": "Closes AWS Organizations accounts tagged organizations:account-closure=REQUESTED and marks them ACKNOWLEDGED.",
          "StartAt": "ListAccounts",
          "States": {
            "ListAccounts": {
              "Type": "Task",
              "Comment": "List the first page of accounts in the organization.",
              "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:listAccounts",
              "ResultPath": "$.page",
              "Next": "ProcessAccountPage",
              "Retry": [
                {
                  "ErrorEquals": [
                    "Organizations.ThrottlingException",
                    "ThrottlingException",
                    "Organizations.TooManyRequestsException",
                    "TooManyRequestsException"
                  ],
                  "IntervalSeconds": 2,
                  "MaxAttempts": 6,
                  "BackoffRate": 2.0,
                  "MaxDelaySeconds": 60
                },
                {
                  "ErrorEquals": [
                    "Organizations.ConcurrentModificationException",
                    "ConcurrentModificationException",
                    "Organizations.ServiceException",
                    "ServiceException"
                  ],
                  "IntervalSeconds": 3,
                  "MaxAttempts": 5,
                  "BackoffRate": 2.0,
                  "MaxDelaySeconds": 60
                },
                {
                  "ErrorEquals": [
                    "Organizations.OrganizationsNotInUseException",
                    "OrganizationsNotInUseException"
                  ],
                  "IntervalSeconds": 5,
                  "MaxAttempts": 2,
                  "BackoffRate": 2.0
                }
              ],
              "Catch": [
                {
                  "ErrorEquals": [
                    "States.ALL"
                  ],
                  "ResultPath": "$.error",
                  "Next": "WorkflowFailed"
                }
              ]
            },
            "ProcessAccountPage": {
              "Type": "Map",
              "Comment": "Evaluate every account returned on the current page.",
              "ItemsPath": "$.page.Accounts",
              "ItemSelector": {
                "account.$": "$$.Map.Item.Value"
              },
              "ItemProcessor": {
                "ProcessorConfig": {
                  "Mode": "INLINE"
                },
                "StartAt": "ListAccountTags",
                "States": {
                  "ListAccountTags": {
                    "Type": "Task",
                    "Comment": "Read the tags attached to the account.",
                    "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:listTagsForResource",
                    "Parameters": {
                      "ResourceId.$": "$.account.Id"
                    },
                    "ResultPath": "$.tagResult",
                    "Next": "MatchClosureTag",
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.ThrottlingException",
                          "ThrottlingException",
                          "Organizations.TooManyRequestsException",
                          "TooManyRequestsException"
                        ],
                        "IntervalSeconds": 2,
                        "MaxAttempts": 6,
                        "BackoffRate": 2.0,
                        "MaxDelaySeconds": 60
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.ConcurrentModificationException",
                          "ConcurrentModificationException",
                          "Organizations.ServiceException",
                          "ServiceException"
                        ],
                        "IntervalSeconds": 3,
                        "MaxAttempts": 5,
                        "BackoffRate": 2.0,
                        "MaxDelaySeconds": 60
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.OrganizationsNotInUseException",
                          "OrganizationsNotInUseException"
                        ],
                        "IntervalSeconds": 5,
                        "MaxAttempts": 2,
                        "BackoffRate": 2.0
                      }
                    ],
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": "$.error",
                        "Next": "RecordAccountError"
                      }
                    ]
                  },
                  "MatchClosureTag": {
                    "Type": "Map",
                    "Comment": "Scan the returned tags for key organizations:account-closure with value REQUESTED.",
                    "ItemsPath": "$.tagResult.Tags",
                    "ItemSelector": {
                      "tag.$": "$$.Map.Item.Value"
                    },
                    "MaxConcurrency": 1,
                    "ItemProcessor": {
                      "ProcessorConfig": {
                        "Mode": "INLINE"
                      },
                      "StartAt": "IsClosureTag",
                      "States": {
                        "IsClosureTag": {
                          "Type": "Choice",
                          "Choices": [
                            {
                              "And": [
                                {
                                  "Variable": "$.tag.Key",
                                  "StringEquals": "organizations:account-closure"
                                },
                                {
                                  "Variable": "$.tag.Value",
                                  "StringEquals": "REQUESTED"
                                }
                              ],
                              "Next": "TagMatched"
                            }
                          ],
                          "Default": "TagNotMatched"
                        },
                        "TagMatched": {
                          "Type": "Pass",
                          "Result": "MATCH",
                          "End": true
                        },
                        "TagNotMatched": {
                          "Type": "Pass",
                          "Result": "NO_MATCH",
                          "End": true
                        }
                      }
                    },
                    "ResultPath": "$.tagMatches",
                    "Next": "EvaluateClosureTag",
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": "$.error",
                        "Next": "RecordAccountError"
                      }
                    ]
                  },
                  "EvaluateClosureTag": {
                    "Type": "Pass",
                    "Comment": "Reduce the tag scan to a single boolean flag.",
                    "Parameters": {
                      "account.$": "$.account",
                      "tagMatches.$": "$.tagMatches",
                      "isClosureRequested.$": "States.ArrayContains($.tagMatches, 'MATCH')"
                    },
                    "Next": "IsClosureRequested"
                  },
                  "IsClosureRequested": {
                    "Type": "Choice",
                    "Comment": "Only accounts explicitly tagged for closure continue.",
                    "Choices": [
                      {
                        "Variable": "$.isClosureRequested",
                        "BooleanEquals": true,
                        "Next": "DescribeAccount"
                      }
                    ],
                    "Default": "SkipAccount"
                  },
                  "DescribeAccount": {
                    "Type": "Task",
                    "Comment": "Describe the account to confirm its current status.",
                    "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:describeAccount",
                    "Parameters": {
                      "AccountId.$": "$.account.Id"
                    },
                    "ResultPath": "$.accountDetails",
                    "Next": "IsAccountActive",
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.ThrottlingException",
                          "ThrottlingException",
                          "Organizations.TooManyRequestsException",
                          "TooManyRequestsException"
                        ],
                        "IntervalSeconds": 2,
                        "MaxAttempts": 6,
                        "BackoffRate": 2.0,
                        "MaxDelaySeconds": 60
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.ConcurrentModificationException",
                          "ConcurrentModificationException",
                          "Organizations.ServiceException",
                          "ServiceException"
                        ],
                        "IntervalSeconds": 3,
                        "MaxAttempts": 5,
                        "BackoffRate": 2.0,
                        "MaxDelaySeconds": 60
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.OrganizationsNotInUseException",
                          "OrganizationsNotInUseException"
                        ],
                        "IntervalSeconds": 5,
                        "MaxAttempts": 2,
                        "BackoffRate": 2.0
                      }
                    ],
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": "$.error",
                        "Next": "RecordAccountError"
                      }
                    ]
                  },
                  "IsAccountActive": {
                    "Type": "Choice",
                    "Comment": "Only ACTIVE accounts can be closed; SUSPENDED and PENDING_CLOSURE are skipped.",
                    "Choices": [
                      {
                        "Variable": "$.accountDetails.Account.Status",
                        "StringEquals": "ACTIVE",
                        "Next": "CloseAccount"
                      }
                    ],
                    "Default": "SkipAccount"
                  },
                  "CloseAccount": {
                    "Type": "Task",
                    "Comment": "Close the ACTIVE account that was tagged for closure.",
                    "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:closeAccount",
                    "Parameters": {
                      "AccountId.$": "$.account.Id"
                    },
                    "ResultPath": "$.closeResult",
                    "Next": "TagAccountAcknowledged",
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.ThrottlingException",
                          "ThrottlingException",
                          "Organizations.TooManyRequestsException",
                          "TooManyRequestsException"
                        ],
                        "IntervalSeconds": 2,
                        "MaxAttempts": 6,
                        "BackoffRate": 2.0,
                        "MaxDelaySeconds": 60
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.ConcurrentModificationException",
                          "ConcurrentModificationException",
                          "Organizations.ServiceException",
                          "ServiceException"
                        ],
                        "IntervalSeconds": 3,
                        "MaxAttempts": 5,
                        "BackoffRate": 2.0,
                        "MaxDelaySeconds": 60
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.OrganizationsNotInUseException",
                          "OrganizationsNotInUseException"
                        ],
                        "IntervalSeconds": 5,
                        "MaxAttempts": 2,
                        "BackoffRate": 2.0
                      }
                    ],
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": "$.error",
                        "Next": "RecordAccountError"
                      }
                    ]
                  },
                  "TagAccountAcknowledged": {
                    "Type": "Task",
                    "Comment": "Overwrite the closure tag so the account is not processed again.",
                    "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:tagResource",
                    "Parameters": {
                      "ResourceId.$": "$.account.Id",
                      "Tags": [
                        {
                          "Key": "organizations:account-closure",
                          "Value": "ACKNOWLEDGED"
                        }
                      ]
                    },
                    "ResultPath": "$.tagAcknowledged",
                    "Next": "AccountClosed",
                    "Retry": [
                      {
                        "ErrorEquals": [
                          "Organizations.ThrottlingException",
                          "ThrottlingException",
                          "Organizations.TooManyRequestsException",
                          "TooManyRequestsException"
                        ],
                        "IntervalSeconds": 2,
                        "MaxAttempts": 6,
                        "BackoffRate": 2.0,
                        "MaxDelaySeconds": 60
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.ConcurrentModificationException",
                          "ConcurrentModificationException",
                          "Organizations.ServiceException",
                          "ServiceException"
                        ],
                        "IntervalSeconds": 3,
                        "MaxAttempts": 5,
                        "BackoffRate": 2.0,
                        "MaxDelaySeconds": 60
                      },
                      {
                        "ErrorEquals": [
                          "Organizations.OrganizationsNotInUseException",
                          "OrganizationsNotInUseException"
                        ],
                        "IntervalSeconds": 5,
                        "MaxAttempts": 2,
                        "BackoffRate": 2.0
                      }
                    ],
                    "Catch": [
                      {
                        "ErrorEquals": [
                          "States.ALL"
                        ],
                        "ResultPath": "$.error",
                        "Next": "RecordAccountError"
                      }
                    ]
                  },
                  "AccountClosed": {
                    "Type": "Pass",
                    "Comment": "Terminal success path for a single account.",
                    "Parameters": {
                      "accountId.$": "$.account.Id",
                      "accountName.$": "$.account.Name",
                      "result": "CLOSED_AND_ACKNOWLEDGED"
                    },
                    "End": true
                  },
                  "SkipAccount": {
                    "Type": "Pass",
                    "Comment": "Terminal skip path: the account is not tagged for closure or is not ACTIVE.",
                    "Parameters": {
                      "accountId.$": "$.account.Id",
                      "accountName.$": "$.account.Name",
                      "result": "SKIPPED"
                    },
                    "End": true
                  },
                  "RecordAccountError": {
                    "Type": "Pass",
                    "Comment": "Record the account-level failure with its account ID and error context; the REQUESTED tag is left in place so the account is retried on the next hourly run.",
                    "Parameters": {
                      "accountId.$": "$.account.Id",
                      "accountName.$": "$.account.Name",
                      "result": "ERROR",
                      "error.$": "$.error"
                    },
                    "End": true
                  }
                }
              },
              "MaxConcurrency": 1,
              "ResultPath": "$.pageResults",
              "Next": "HasMoreAccountPages",
              "Retry": [
                {
                  "ErrorEquals": [
                    "Organizations.ThrottlingException",
                    "ThrottlingException",
                    "Organizations.TooManyRequestsException",
                    "TooManyRequestsException"
                  ],
                  "IntervalSeconds": 2,
                  "MaxAttempts": 6,
                  "BackoffRate": 2.0,
                  "MaxDelaySeconds": 60
                }
              ],
              "Catch": [
                {
                  "ErrorEquals": [
                    "States.ALL"
                  ],
                  "ResultPath": "$.error",
                  "Next": "WorkflowFailed"
                }
              ]
            },
            "HasMoreAccountPages": {
              "Type": "Choice",
              "Comment": "Loop back while organizations:ListAccounts returns a usable NextToken.",
              "Choices": [
                {
                  "And": [
                    {
                      "Variable": "$.page.NextToken",
                      "IsPresent": true
                    },
                    {
                      "Not": {
                        "Variable": "$.page.NextToken",
                        "StringEquals": ""
                      }
                    }
                  ],
                  "Next": "ListAccountsNextPage"
                }
              ],
              "Default": "WorkflowCompleted"
            },
            "ListAccountsNextPage": {
              "Type": "Task",
              "Comment": "List the next page of accounts using the pagination token.",
              "Resource": "arn:${AWS::Partition}:states:::aws-sdk:organizations:listAccounts",
              "Parameters": {
                "NextToken.$": "$.page.NextToken"
              },
              "ResultPath": "$.page",
              "Next": "ProcessAccountPage",
              "Retry": [
                {
                  "ErrorEquals": [
                    "Organizations.ThrottlingException",
                    "ThrottlingException",
                    "Organizations.TooManyRequestsException",
                    "TooManyRequestsException"
                  ],
                  "IntervalSeconds": 2,
                  "MaxAttempts": 6,
                  "BackoffRate": 2.0,
                  "MaxDelaySeconds": 60
                },
                {
                  "ErrorEquals": [
                    "Organizations.ConcurrentModificationException",
                    "ConcurrentModificationException",
                    "Organizations.ServiceException",
                    "ServiceException"
                  ],
                  "IntervalSeconds": 3,
                  "MaxAttempts": 5,
                  "BackoffRate": 2.0,
                  "MaxDelaySeconds": 60
                },
                {
                  "ErrorEquals": [
                    "Organizations.OrganizationsNotInUseException",
                    "OrganizationsNotInUseException"
                  ],
                  "IntervalSeconds": 5,
                  "MaxAttempts": 2,
                  "BackoffRate": 2.0
                }
              ],
              "Catch": [
                {
                  "ErrorEquals": [
                    "States.ALL"
                  ],
                  "ResultPath": "$.error",
                  "Next": "WorkflowFailed"
                }
              ]
            },
            "WorkflowCompleted": {
              "Type": "Succeed"
            },
            "WorkflowFailed": {
              "Type": "Fail",
              "Error": "AccountClosureWorkflowFailed",
              "Cause": "The account closure workflow could not complete. Inspect the execution history and the CloudWatch log group for the recorded account identifiers and error details."
            }
          }
        }

  AccountClosureEventBridgeRole:
    Type: AWS::IAM::Role
    Properties:
      Description: Allows the hourly EventBridge schedule to start the account closure workflow.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Sid: AllowEventBridgeServiceToAssumeRole
            Effect: Allow
            Principal:
              Service: events.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: StartAccountClosureStateMachine
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: AllowStartExecutionOfAccountClosureWorkflow
                Effect: Allow
                Action:
                  - states:StartExecution
                Resource: !Ref AccountClosureStateMachine

  AccountClosureScheduleRule:
    Type: AWS::Events::Rule
    Properties:
      Name: account-closure-hourly-schedule
      Description: Runs the AWS Organizations account closure workflow every hour.
      State: ENABLED
      ScheduleExpression: rate(1 hour)
      Targets:
        - Id: AccountClosureStateMachineTarget
          Arn: !Ref AccountClosureStateMachine
          RoleArn: !GetAtt AccountClosureEventBridgeRole.Arn
          Input: '{"executionNamePrefix": "account-closure-workflow"}'

Outputs:
  StateMachineArn:
    Description: ARN of the account closure EXPRESS state machine.
    Value: !Ref AccountClosureStateMachine
  StateMachineName:
    Description: Name of the account closure EXPRESS state machine.
    Value: !GetAtt AccountClosureStateMachine.Name
  EventBridgeRuleArn:
    Description: ARN of the hourly EventBridge schedule rule.
    Value: !GetAtt AccountClosureScheduleRule.Arn
  EventBridgeRuleName:
    Description: Name of the hourly EventBridge schedule rule.
    Value: !Ref AccountClosureScheduleRule
  ExecutionLogGroupName:
    Description: CloudWatch Logs log group holding 365 days of workflow execution data.
    Value: !Ref AccountClosureLogGroup

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Amazon Verified Permissions policy store that implements Cedar-based access
  control for a bookstore application. The store is created with strict schema
  validation over the Bookstore namespace (Role, User, Book entities plus the
  View and ViewWithPremiumOffers actions), is populated with static Cedar
  policies, and its policy store ID is published to an SSM parameter for
  downstream consumers.

Resources:

  # ---------------------------------------------------------------------------
  # Verified Permissions policy store with strict schema validation
  # ---------------------------------------------------------------------------
  BookstorePolicyStore:
    Type: AWS::VerifiedPermissions::PolicyStore
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      ValidationSettings:
        Mode: STRICT
      Schema:
        CedarJson: |
          {
            "Bookstore": {
              "entityTypes": {
                "Role": {
                  "shape": {
                    "type": "Record",
                    "attributes": {}
                  }
                },
                "User": {
                  "memberOfTypes": [
                    "Role"
                  ],
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "yearsAsMember": {
                        "type": "Long",
                        "required": false
                      }
                    }
                  }
                },
                "Book": {
                  "shape": {
                    "type": "Record",
                    "attributes": {
                      "owner": {
                        "type": "Entity",
                        "name": "User",
                        "required": true
                      }
                    }
                  }
                }
              },
              "actions": {
                "View": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                },
                "ViewWithPremiumOffers": {
                  "appliesTo": {
                    "principalTypes": [
                      "User"
                    ],
                    "resourceTypes": [
                      "Book"
                    ],
                    "context": {
                      "type": "Record",
                      "attributes": {
                        "region": {
                          "type": "String",
                          "required": true
                        }
                      }
                    }
                  }
                }
              }
            }
          }

  # ---------------------------------------------------------------------------
  # Policy 1 - Administrators may view any book
  # ---------------------------------------------------------------------------
  AdminViewAnyBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Admin role to view any book.
          Statement: |
            permit (
              principal in Bookstore::Role::"Admin",
              action == Bookstore::Action::"View",
              resource
            );

  # ---------------------------------------------------------------------------
  # Policy 2 - One specific administrator is explicitly denied (forbid wins)
  # ---------------------------------------------------------------------------
  BlockSpecificAdminPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: >-
            Forbid the specifically named administrator from viewing books,
            overriding the general Admin role permission.
          Statement: |
            forbid (
              principal == Bookstore::User::"blocked-admin",
              action == Bookstore::Action::"View",
              resource
            );

  # ---------------------------------------------------------------------------
  # Policy 3 - Publishers may view only the books they own
  # ---------------------------------------------------------------------------
  PublisherViewOwnedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit users in the Publisher role to view only the books they own.
          Statement: |
            permit (
              principal in Bookstore::Role::"Publisher",
              action == Bookstore::Action::"View",
              resource
            )
            when {
              resource.owner == principal
            };

  # ---------------------------------------------------------------------------
  # Policy 4 - One specific user may view one specific book
  # ---------------------------------------------------------------------------
  NamedUserViewNamedBookPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: Permit one specifically named user to view one specifically named book.
          Statement: |
            permit (
              principal == Bookstore::User::"user-alice",
              action == Bookstore::Action::"View",
              resource == Bookstore::Book::"book-1984"
            );

  # ---------------------------------------------------------------------------
  # Policy 5 - Customers with two or more years of membership see premium offers
  # ---------------------------------------------------------------------------
  CustomerPremiumOffersPermitPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: >-
            Permit users in the Customer role to view premium offers once they
            have been members for two years or more.
          Statement: |
            permit (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal has yearsAsMember && principal.yearsAsMember >= 2
            };

  # ---------------------------------------------------------------------------
  # Policy 6 - Customers with less than two years of membership are denied
  # ---------------------------------------------------------------------------
  CustomerPremiumOffersForbidPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: >-
            Forbid customers with less than two years of membership from
            viewing premium offers.
          Statement: |
            forbid (
              principal in Bookstore::Role::"Customer",
              action == Bookstore::Action::"ViewWithPremiumOffers",
              resource
            )
            when {
              principal has yearsAsMember && principal.yearsAsMember < 2
            };

  # ---------------------------------------------------------------------------
  # Policy 7 - Both actions are denied outside the United States
  # ---------------------------------------------------------------------------
  RestrictRegionPolicy:
    Type: AWS::VerifiedPermissions::Policy
    Properties:
      PolicyStoreId: !Ref BookstorePolicyStore
      Definition:
        Static:
          Description: >-
            Forbid both the View and ViewWithPremiumOffers actions whenever the
            request context region is not the United States.
          Statement: |
            forbid (
              principal,
              action in [
                Bookstore::Action::"View",
                Bookstore::Action::"ViewWithPremiumOffers"
              ],
              resource
            )
            when {
              context.region != "United States"
            };

  # ---------------------------------------------------------------------------
  # SSM parameter publishing the policy store ID for downstream consumers
  # ---------------------------------------------------------------------------
  PolicyStoreIdParameter:
    Type: AWS::SSM::Parameter
    Properties:
      Name: !Sub '/${AWS::StackName}/bookstore/verified-permissions/policy-store-id'
      Type: String
      Value: !GetAtt BookstorePolicyStore.PolicyStoreId
      Description: Policy store ID of the bookstore Amazon Verified Permissions policy store.

Outputs:

  PolicyStoreId:
    Description: Identifier of the bookstore Amazon Verified Permissions policy store.
    Value: !GetAtt BookstorePolicyStore.PolicyStoreId

  PolicyStoreArn:
    Description: ARN of the bookstore Amazon Verified Permissions policy store.
    Value: !GetAtt BookstorePolicyStore.Arn

  PolicyStoreIdParameterName:
    Description: Name of the SSM parameter that holds the policy store ID.
    Value: !Ref PolicyStoreIdParameter

AWSTemplateFormatVersion: '2010-09-09'
Description: >-
  Self-contained AWS AppSync GraphQL API "TodoAPIwithJs" with API key
  authentication, backed by a DynamoDB table that has an OwnerIndex global
  secondary index. Uses APPSYNC_JS 1.0.0 JavaScript pipeline resolvers and
  individual function configurations for full CRUD, owner-index query, and
  real-time subscriptions.

Resources:

  # ---------------------------------------------------------------
  # DynamoDB table for Todo items with OwnerIndex GSI
  # ---------------------------------------------------------------
  TodoTable:
    Type: AWS::DynamoDB::Table
    DeletionPolicy: Retain
    UpdateReplacePolicy: Retain
    Properties:
      TableName: !Sub '${AWS::StackName}-todos'
      BillingMode: PAY_PER_REQUEST
      SSESpecification:
        SSEEnabled: true
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: OwnerIndex
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL

  # ---------------------------------------------------------------
  # IAM role assumed by AppSync to access the Todo table + OwnerIndex
  # ---------------------------------------------------------------
  AppSyncDynamoDBRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: !Sub '${AWS::StackName}-appsync-dynamodb-role'
      Description: Least-privilege role used by the TodoAPIwithJs AppSync DynamoDB data source.
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncTodoDynamoDBAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Sid: TodoTableAndIndexAccess
                Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub '${TodoTable.Arn}/index/OwnerIndex'

  # ---------------------------------------------------------------
  # AppSync GraphQL API + API key
  # ---------------------------------------------------------------
  TodoAPIwithJs:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: TodoAPIwithJs
      AuthenticationType: API_KEY
      XrayEnabled: true
      LogConfig:
        CloudWatchLogsRoleArn: !GetAtt AppSyncCloudWatchLogsRole.Arn
        FieldLogLevel: ERROR

  TodoAPIKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      Description: API key for the TodoAPIwithJs GraphQL API

  AppSyncCloudWatchLogsRole:
    Type: AWS::IAM::Role
    Properties:
      RoleName: !Sub '${AWS::StackName}-appsync-logs-role'
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: AppSyncCloudWatchLogsAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - logs:CreateLogGroup
                  - logs:CreateLogStream
                  - logs:PutLogEvents
                Resource:
                  - !Sub 'arn:${AWS::Partition}:logs:${AWS::Region}:${AWS::AccountId}:log-group:/aws/appsync/apis/*'

  # ---------------------------------------------------------------
  # GraphQL schema
  # ---------------------------------------------------------------
  TodoGraphQLSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      Definition: |
        type Todo {
          id: ID!
          owner: String
          name: String
          description: String
          createdAt: String
          updatedAt: String
        }

        type TodoConnection {
          items: [Todo]
          nextToken: String
        }

        input CreateTodoInput {
          id: ID
          owner: String!
          name: String!
          description: String
        }

        input UpdateTodoInput {
          id: ID!
          owner: String
          name: String
          description: String
        }

        type Query {
          getTodo(id: ID!): Todo
          listTodos(limit: Int, nextToken: String): TodoConnection
          todosByOwner(owner: String!, limit: Int, nextToken: String): TodoConnection
        }

        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }

        type Subscription {
          onCreateTodo: Todo
            @aws_subscribe(mutations: ["createTodo"])
          onUpdateTodo: Todo
            @aws_subscribe(mutations: ["updateTodo"])
          onDeleteTodo: Todo
            @aws_subscribe(mutations: ["deleteTodo"])
        }

        schema {
          query: Query
          mutation: Mutation
          subscription: Subscription
        }

  # ---------------------------------------------------------------
  # AppSync DynamoDB data source
  # ---------------------------------------------------------------
  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      Name: TodoTableDataSource
      Description: DynamoDB data source for the Todo table and OwnerIndex.
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncDynamoDBRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref 'AWS::Region'
        UseCallerCredentials: false

  # ---------------------------------------------------------------
  # AppSync JavaScript function configurations (APPSYNC_JS 1.0.0)
  # ---------------------------------------------------------------
  CreateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      Name: createTodo
      Description: Creates a Todo item in DynamoDB.
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const now = util.time.nowISO8601();
          const id = input.id || util.autoId();

          const item = {
            id: id,
            owner: input.owner,
            name: input.name,
            description: input.description,
            createdAt: now,
            updatedAt: now,
          };

          Object.keys(item).forEach(function (k) {
            if (item[k] === undefined || item[k] === null) {
              delete item[k];
            }
          });

          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id: id }),
            attributeValues: util.dynamodb.toMapValues(item),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type, ctx.result);
          }
          return ctx.result;
        }

  UpdateTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      Name: updateTodo
      Description: Updates an existing Todo item in DynamoDB.
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const input = ctx.args.input;
          const id = input.id;
          const now = util.time.nowISO8601();

          const updates = { updatedAt: now };
          Object.keys(input).forEach(function (k) {
            if (k !== 'id' && input[k] !== undefined && input[k] !== null) {
              updates[k] = input[k];
            }
          });

          const expressionNames = {};
          const expressionValues = {};
          const setClauses = [];

          Object.keys(updates).forEach(function (k, i) {
            const nameKey = '#f' + i;
            const valueKey = ':v' + i;
            expressionNames[nameKey] = k;
            expressionValues[valueKey] = updates[k];
            setClauses.push(nameKey + ' = ' + valueKey);
          });

          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id: id }),
            update: {
              expression: 'SET ' + setClauses.join(', '),
              expressionNames: expressionNames,
              expressionValues: util.dynamodb.toMapValues(expressionValues),
            },
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type, ctx.result);
          }
          return ctx.result;
        }

  DeleteTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      Name: deleteTodo
      Description: Deletes a Todo item from DynamoDB.
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const id = ctx.args.id;
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type, ctx.result);
          }
          return ctx.result;
        }

  GetTodoFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      Name: getTodo
      Description: Retrieves a single Todo item by id from DynamoDB.
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const id = ctx.args.id;
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: id }),
          };
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type, ctx.result);
          }
          return ctx.result;
        }

  ListTodosFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      Name: listTodos
      Description: Scans the Todo table with pagination support.
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const limit = ctx.args.limit || 50;
          const nextToken = ctx.args.nextToken || null;

          const req = {
            operation: 'Scan',
            limit: limit,
          };
          if (nextToken) {
            req.nextToken = nextToken;
          }
          return req;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type, ctx.result);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  TodosByOwnerFunction:
    Type: AWS::AppSync::FunctionConfiguration
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      Name: todosByOwner
      Description: Queries the OwnerIndex GSI for todos belonging to an owner.
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';

        export function request(ctx) {
          const owner = ctx.args.owner;
          const limit = ctx.args.limit || 50;
          const nextToken = ctx.args.nextToken || null;

          const req = {
            operation: 'Query',
            index: 'OwnerIndex',
            query: {
              expression: 'owner = :owner',
              expressionValues: util.dynamodb.toMapValues({ ':owner': owner }),
            },
            limit: limit,
          };
          if (nextToken) {
            req.nextToken = nextToken;
          }
          return req;
        }

        export function response(ctx) {
          if (ctx.error) {
            util.error(ctx.error.message, ctx.error.type, ctx.result);
          }
          return {
            items: ctx.result.items,
            nextToken: ctx.result.nextToken,
          };
        }

  # ---------------------------------------------------------------
  # Pipeline resolvers for Query and Mutation fields
  # ---------------------------------------------------------------
  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      TypeName: Mutation
      FieldName: createTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt CreateTodoFunction.FunctionId

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt UpdateTodoFunction.FunctionId

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt DeleteTodoFunction.FunctionId

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      TypeName: Query
      FieldName: getTodo
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt GetTodoFunction.FunctionId

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      TypeName: Query
      FieldName: listTodos
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt ListTodosFunction.FunctionId

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    DependsOn: TodoGraphQLSchema
    Properties:
      ApiId: !GetAtt TodoAPIwithJs.ApiId
      TypeName: Query
      FieldName: todosByOwner
      Kind: PIPELINE
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {};
        }

        export function response(ctx) {
          return ctx.prev.result;
        }
      PipelineConfig:
        Functions:
          - !GetAtt TodosByOwnerFunction.FunctionId

# ---------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------
Outputs:
  GraphQLApiId:
    Description: Identifier of the TodoAPIwithJs AppSync GraphQL API.
    Value: !GetAtt TodoAPIwithJs.ApiId

  GraphQLApiEndpoint:
    Description: HTTPS endpoint clients use to call the TodoAPIwithJs GraphQL API.
    Value: !GetAtt TodoAPIwithJs.GraphQLUrl

  ApiKeyId:
    Description: Identifier of the API key created for the TodoAPIwithJs GraphQL API.
    Value: !GetAtt TodoAPIKey.ApiKeyId

  DynamoDBTableName:
    Description: Name of the DynamoDB table that stores Todo items.
    Value: !Ref TodoTable

  DynamoDBTableArn:
    Description: ARN of the DynamoDB table that stores Todo items.
    Value: !GetAtt TodoTable.Arn
